type DeepPartial<T> = T extends object
  ? { [K in keyof T]?: DeepPartial<T[K]> }
  : T;

// used to type a partial config override:
//   function merge<T>(base: T, override: DeepPartial<T>): T

type Cfg = {
  name: string;
  tags: string[];
  handler: () => void;
  nested: { retries: number };
};
type Override = DeepPartial<Cfg>;
